describe('Async Image Upload with Progress Percentage', () => {
  beforeEach(() => {
    cy.visit('/upload-image');
  });

  it('should display progress percentage during async image upload', () => {
    // Intercept the upload API call
    cy.intercept('POST', '/api/upload/image', {
      statusCode: 200,
      body: {
        message: 'Image uploaded successfully',
        fileId: '12345'
      }
    }).as('uploadImage');

    // Get the upload input and file selector
    cy.get('[data-testid="upload-input"]').selectFile('cypress/fixtures/test-image.jpg', {
      force: true
    });

    // Verify progress bar is visible
    cy.get('[data-testid="progress-bar"]').should('be.visible');

    // Verify progress percentage is displayed
    cy.get('[data-testid="progress-percentage"]').should('contain', '0%');

    // Wait for the upload to start
    cy.wait('@uploadImage');

    // Verify progress percentage updates
    cy.get('[data-testid="progress-percentage"]').should('contain', '25%');

    // Verify progress bar is now partially filled
    cy.get('[data-testid="progress-bar"]').should('have.css', 'width', '25%');

    // Wait for the upload to complete
    cy.wait('@uploadImage');

    // Verify progress percentage reaches 100%
    cy.get('[data-testid="progress-percentage"]').should('contain', '100%');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Image uploaded successfully');

    // Verify file ID is displayed
    cy.get('[data-testid="file-id"]').should('contain', '12345');
  });

  it('should handle upload failure and display error message', () => {
    // Intercept the upload API call with error response
    cy.intercept('POST', '/api/upload/image', {
      statusCode: 500,
      body: {
        error: 'Server error during upload'
      }
    }).as('uploadImageError');

    // Get the upload input and file selector
    cy.get('[data-testid="upload-input"]').selectFile('cypress/fixtures/test-image.jpg', {
      force: true
    });

    // Verify progress bar is visible
    cy.get('[data-testid="progress-bar"]').should('be.visible');

    // Wait for the upload to start
    cy.wait('@uploadImageError');

    // Verify progress percentage updates
    cy.get('[data-testid="progress-percentage"]').should('contain', '50%');

    // Verify progress bar is now partially filled
    cy.get('[data-testid="progress-bar"]').should('have.css', 'width', '50%');

    // Wait for the upload to fail
    cy.wait('@uploadImageError');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Upload failed');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Verify file ID is not displayed
    cy.get('[data-testid="file-id"]').should('not.exist');
  });
});
